                    },
                    "mergeStrategy": "arrayMergeById",
                    "title": "Milestones",
                    "type": "array"
                },
                "minValue": {
                    "$ref": "#/definitions/Value",
                    "description": "The minimum estimated value of the procurement.",
                    "title": "Minimum value"
                },
                "numberOfTenderers": {
                    "description": "The number of entities who submit a tender.",
                    "mergeStrategy": "ocdsVersion",
                    "title": "Number of tenderers",
                    "type": [
                        "integer",
                        "null"
                    ]
                },
                "procurementMethod": {
                    "description": "Specify tendering method against the [method codelist](http://standard.open-contracting.org/1.0/en/schema/codelists/#method) as per [GPA definitions](http://www.wto.org/english/docs_e/legal_e/rev-gpr-94_01_e.htm) of Open, Selective, Limited",
                    "enum": [
                        "open",
                        "selective",
                        "limited",
                        null
                    ],
                    "mergeStrategy": "ocdsVersion",
                    "title": "Procurement method",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "procurementMethodDetails": {
                    "description": "Additional detail on the procurement method used. This field may be used to provide the local name of the particular procurement method used.",
                    "mergeStrategy": "ocdsVersion",
                    "title": "Procurement method details",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "procurementMethodRationale": {
                    "description": "Rationale of procurement method, especially in the case of Limited tendering.",
                    "mergeStrategy": "ocdsVersion",
                    "title": "Procurement method rationale",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "procuringEntity": {
                    "$ref": "#/definitions/Organization",
                    "description": "The entity managing the procurement, which may be different from the buyer who is paying / using the items being procured.",
                    "title": "Procuring entity"
                },
                "status": {
                    "description": "The current status of the tender based on the [tenderStatus codelist](http://standard.open-contracting.org/1.0/en/schema/codelists/#tender-status)",
                    "enum": [
                        "planned",
                        "active",
                        "cancelled",
                        "unsuccessful",
                        "complete",
                        null
                    ],
                    "mergeStrategy": "ocdsVersion",
                    "title": "Tender status",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "submissionMethod": {
                    "description": "Specify the method by which bids must be submitted, in person, written, or electronic auction. Using the [submission method codelist](http://standard.open-contracting.org/1.0/en/schema/codelists/#submission-method)",
                    "items": {
                        "type": "string"
                    },
                    "mergeStrategy": "ocdsVersion",
                    "title": "Submission method",
                    "type": [
                        "array",
                        "null"
                    ]
                },
                "submissionMethodDetails": {
                    "description": "Any detailed or further information on the submission method. This may include the address, e-mail address or online service to which bids should be submitted, and any special requirements to be followed for submissions.",
                    "mergeStrategy": "ocdsVersion",
                    "title": "Submission method details",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "tenderPeriod": {
                    "$ref": "#/definitions/Period",
